 "content": "def transform(grid):
    """Stamp the embedded horizontal motif, centered on each isolated marker."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The source motif is the longest contiguous non-background run.
    best = None
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            run = row[start:c]
            if best is None or len(run) > len(best[2]):
                best = (r, start, run)
    if best is None or len(best[2]) < 2:
        return [row[:] for row in grid]
    motif_row, motif_start, motif = best
    n = len(motif)
    out = [row[:] for row in grid]

    # The marker is the central cell of the motif; retain the embedded source.
    # Markers are non-background singleton colors not belonging to the source run.
    markers = []
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == bg:
                continue
            if r == motif_row and motif_start <= c < motif_start + n:
                continue
            markers.append((r, c))

    for r, c in markers:
        left = c - n // 2
        for j, value in enumerate(motif):
            x = left + j
            if 0 <= x < w:
                out[r][x] = value
    return out

